        s[--len] = '\0';
    }

    int last[256];
    for (int i = 0; i < 256; i++) last[i] = -1;

    int left = 0, max_len = 0;
    for (int right = 0; right < len; right++) {
        unsigned char c = (unsigned char)s[right];
        if (last[c] >= left) {
            left = last[c] + 1;
        }
        last[c] = right;
        int cur_len = right - left + 1;
        if (cur_len > max_len) max_len = cur_len;
    }
    printf("%d\n", max_len);
    return 0;
}

