int main() {
    int tree[1005];
    int n = 0;
    while (scanf("%d", &tree[n]) == 1) {
        n++;
        char c = getchar();
        if (c == '\n' || c == EOF) break;
    }
    // For complete binary tree levels: reverse each level
    int levelStart = 0;
    int levelSize = 1;
    while (levelStart < n) {
        int levelEnd = levelStart + levelSize;
        if (levelEnd > n) levelEnd = n;
        for (int i = levelStart, j = levelEnd - 1; i < j; i++, j--) {
            int temp = tree[i];
            tree[i] = tree[j];
            tree[j] = temp;
        }
        levelStart = levelEnd;
        levelSize *= 2;
    }
    for (int i = 0; i < n; i++) {
